input.command:
# Batch process file extensions
python3 <<'EOF' > /tmp/extlist
# Generate all 2-4 char extensions and test one per line
import subprocess
import string

chars = string.ascii_lowercase + string.digits
inputs = []
exts = []
# 2-char
for a in chars:
    for b in chars:
        exts.append(f"{a}{b}")
# 3-char
for a in chars:
    for b in chars:
        for c in chars:
            exts.append(f"{a}{b}{c}")
# 4-char
for a in chars:
    for b in chars:
        for c in chars:
            for d in chars:
                exts.append(f"{a}{b}{c}{d}")

# Build a big stdin
lines = [f"test.{e}" for e in exts]

# Run in one go
result = subprocess.run(
    ["./executable", "-F", "-T", "-C", "-S"],
    input="\n".join(lines),
    capture_output=True,
    text=True
)
for line in result.stdout.splitlines():
    if line.startswith("files: "):
        match = line[7:]  # after "files: "
        if '.' in match:
            name, ext = match.rsplit('.', 1)
            print(ext)
EOF
sort -u /tmp/extlist > /tmp/extset
wc -l /tmp/extset
cat /tmp/extset

